# 1) Nginx 作为自建 CDN 边缘：缓存键 + 回源 + 回源合并 + stale-while-revalidate
proxy_cache_path /data/cache levels=1:2 keys_zone=edge:200m max_size=50g inactive=7d use_temp_path=off;

upstream origin {
    server origin.example.com:443;
    keepalive 64;
}

server {
    listen 443 ssl http2;
    server_name cdn.example.com;

    location ~* \.(?:js|css|png|jpg|woff2)$ {
        proxy_pass https://origin;
        proxy_set_header Host origin.example.com;
        proxy_ssl_server_name on;

        # 缓存键只纳入白名单 query，避免 utm_* / 时间戳把缓存切碎
        proxy_cache edge;
        proxy_cache_key "$scheme://$host$uri?v=$arg_v";
        proxy_cache_valid 200 301 7d;
        proxy_cache_valid 404 30s;                    # 负缓存防穿透
        proxy_cache_lock on;                          # 回源合并：同一 key 只放一个回源
        proxy_cache_lock_timeout 5s;
        proxy_cache_use_stale updating error timeout http_500 http_502 http_503 http_504;
        proxy_cache_background_update on;             # stale-while-revalidate：过期先返回旧的

        add_header X-Cache-Status $upstream_cache_status always;  # HIT/MISS/EXPIRED/STALE/UPDATING
        add_header Cache-Control "public, max-age=86400, stale-while-revalidate=60";
    }
}

# 2) 验证 CDN 是否生效与命中率
curl -I -H 'Pragma: ' https://cdn.example.com/app.8f3a.js
# 关注头：
#   X-Cache-Status: HIT          // MISS 表示回源
#   Age: 3217                    // 在边缘已经缓存的秒数
#   Cache-Control: public, max-age=31536000, immutable
#   ETag: "a3f1..."              // 下次浏览器带 If-None-Match 走 304

# 3) 厂商 API：先预热再刷新（顺序反了会瞬时打爆源站）
# 预热（preload）：把热点资源主动推到边缘，发版/大促前用
curl -X POST https://cdn.aliyuncs.com/?Action=PushObjectCache \
  -d 'ObjectPath=https://cdn.example.com/app.8f3a.js' -d 'Area=domestic'

# 刷新（refresh）：让旧缓存失效，下次回源拉新，配额有限
curl -X POST https://cdn.aliyuncs.com/?Action=RefreshObjectCaches \
  -d 'ObjectPath=https://cdn.example.com/index.html' -d 'ObjectType=File'
